module.exports = function() {
  const tokens = JSON.parse(process.env.AEL_TOKENS);
  const lines = [
    '<?xml version="1.0" encoding="utf-8"?>',
    '<!--',
    '  AEL Design System — Android XML Resources',
    '  Generated by 09-Build/generators/android-generator.js',
    '  Source: 06-Implementation/tokens/',
    '  DO NOT EDIT — regenerate via: node 09-Build/build.js',
    '-->',
    '<resources>'
  ];

  const categorized = {};
  for (const tok of Object.values(tokens)) {
    if (!categorized[tok.category]) categorized[tok.category] = [];
    categorized[tok.category].push(tok);
  }

  for (const category of Object.keys(categorized).sort()) {
    lines.push(`    <!-- ${category} -->`);

    for (const tok of categorized[category].sort((a, b) => a.id.localeCompare(b.id))) {
      const resName = `ael_${tok.id.replace(/^TK-/, '').replace(/-/g, '_')}`;

      if (tok.type === 'color') {
        lines.push(`    <color name="${resName}">${tok.value}</color>`);
      } else if (tok.type === 'dimension') {
        lines.push(`    <dimen name="${resName}">${tok.value}</dimen>`);
      } else if (tok.type === 'number') {
        lines.push(`    <integer name="${resName}">${tok.value}</integer>`);
      } else if (tok.type === 'fontFamily') {
        const family = tok.value.split(',')[0].trim().replace(/'/g, '');
        lines.push(`    <string name="${resName}">${family}</string>`);
      } else if (tok.type === 'duration') {
        lines.push(`    <integer name="${resName}">${parseInt(tok.value)}</integer>`);
      } else if (tok.type === 'easing') {
        lines.push(`    <string name="${resName}">${tok.value}</string>`);
      } else if (tok.type === 'shadow') {
        lines.push(`    <string name="${resName}">${tok.value}</string>`);
      }
    }
    lines.push('');
  }

  lines.push('</resources>');
  return lines.join('\n');
};
